import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { exportPKCS8, generateKeyPair } from 'jose';
import type { Env } from '../src/types';

let pem: string;
let rotatedPem: string;
const oauthUrl = 'https://oauth2.googleapis.com/token';

function configuration(key = pem, email = 'billing@test-project.iam.gserviceaccount.com'): Env {
  // Only public test identities and keys generated by this test reach the helper.
  return { PACKAGE_NAME: 'com.test.doneat', GOOGLE_SERVICE_ACCOUNT_EMAIL: email, GOOGLE_PRIVATE_KEY: key } as Env;
}
function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>(done => { resolve = done; });
  return { promise, resolve };
}

beforeAll(async () => {
  pem = await exportPKCS8((await generateKeyPair('RS256', { extractable: true })).privateKey);
  rotatedPem = await exportPKCS8((await generateKeyPair('RS256', { extractable: true })).privateKey);
});
beforeEach(() => vi.resetModules());
afterEach(() => vi.restoreAllMocks());

describe('isolate-local Google credentials', () => {
  it('keeps concurrent OAuth exchanges and each purchase query independent', async () => {
    const { getPurchase } = await import('../src/google');
    const entered = deferred<void>();
    const release = deferred<Response>();
    let oauthCalls = 0;
    let purchaseCalls = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async (input, init) => {
      if (String(input) === oauthUrl) { oauthCalls++; entered.resolve(); return (await release.promise).clone(); }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) {
        purchaseCalls++;
        expect(new Headers(init?.headers).get('Authorization')).toBe('Bearer shared-access');
        return Response.json({ purchase: true });
      }
      throw new Error('Unexpected network destination');
    });
    const requests = Array.from({ length: 8 }, (_, index) => getPurchase(configuration(), `purchase-${index}`, true));
    await entered.promise;
    await vi.waitFor(() => expect(oauthCalls).toBe(8));
    release.resolve(Response.json({ access_token: 'shared-access', expires_in: 3600 }));
    expect(await Promise.all(requests)).toHaveLength(8);
    expect(oauthCalls).toBe(8);
    expect(purchaseCalls).toBe(8);
  });

  it('reuses the imported key across token refreshes and email changes, but imports a rotated PEM', async () => {
    const { getPurchase } = await import('../src/google');
    const imports = vi.spyOn(crypto.subtle, 'importKey');
    let oauthCalls = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async input => {
      if (String(input) === oauthUrl) {
        oauthCalls++;
        // Expiring inside the existing 60-second margin forces another OAuth exchange.
        return Response.json({ access_token: `access-${oauthCalls}`, expires_in: 1 });
      }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) return Response.json({});
      throw new Error('Unexpected network destination');
    });
    await getPurchase(configuration(), 'first', true);
    await getPurchase(configuration(), 'refresh', true);
    await getPurchase(configuration(pem, 'rotated-email@test-project.iam.gserviceaccount.com'), 'identity-change', true);
    expect(imports.mock.calls.filter(call => call[0] === 'pkcs8')).toHaveLength(1);
    await getPurchase(configuration(rotatedPem), 'key-change', true);
    expect(imports.mock.calls.filter(call => call[0] === 'pkcs8')).toHaveLength(2);
    expect(oauthCalls).toBe(4);
  });

  it('retries a failed key import instead of caching a rejected Promise', async () => {
    const { getPurchase } = await import('../src/google');
    const imports = vi.spyOn(crypto.subtle, 'importKey').mockRejectedValueOnce(new Error('test import failure'));
    let oauthCalls = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async input => {
      if (String(input) === oauthUrl) { oauthCalls++; return Response.json({ access_token: 'recovered-access', expires_in: 3600 }); }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) return Response.json({});
      throw new Error('Unexpected network destination');
    });
    await expect(getPurchase(configuration(), 'failed-key', true)).rejects.toThrow('test import failure');
    expect(oauthCalls).toBe(0);
    await getPurchase(configuration(), 'retry-key', true);
    expect(imports.mock.calls.filter(call => call[0] === 'pkcs8')).toHaveLength(2);
    expect(oauthCalls).toBe(1);
  });

  it('does not share refreshed access tokens across service-account identities', async () => {
    const { getPurchase } = await import('../src/google');
    const releaseFirst = deferred<Response>();
    const firstEntered = deferred<void>();
    let oauthCalls = 0;
    const used: string[] = [];
    vi.spyOn(globalThis, 'fetch').mockImplementation(async (input, init) => {
      if (String(input) === oauthUrl) {
        oauthCalls++;
        if (oauthCalls === 1) { firstEntered.resolve(); return releaseFirst.promise; }
        return Response.json({ access_token: 'second-identity', expires_in: 3600 });
      }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) {
        used.push(new Headers(init?.headers).get('Authorization')!);
        return Response.json({});
      }
      throw new Error('Unexpected network destination');
    });
    const first = getPurchase(configuration(), 'first', true);
    await firstEntered.promise;
    const next = configuration(pem, 'second@test-project.iam.gserviceaccount.com');
    await getPurchase(next, 'second', true);
    releaseFirst.resolve(Response.json({ access_token: 'first-identity', expires_in: 3600 }));
    await first;
    await getPurchase(next, 'third', true);
    expect(oauthCalls).toBe(2);
    expect(used).toEqual(['Bearer second-identity', 'Bearer first-identity', 'Bearer second-identity']);
  });

  it('failed concurrent exchanges do not prevent a later request from retrying', async () => {
    const { getPurchase } = await import('../src/google');
    const entered = deferred<void>();
    const release = deferred<Response>();
    let oauthCalls = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async input => {
      if (String(input) === oauthUrl) {
        oauthCalls++;
        if (oauthCalls <= 2) { entered.resolve(); return (await release.promise).clone(); }
        return Response.json({ access_token: 'retry-access', expires_in: 3600 });
      }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) return Response.json({});
      throw new Error('Unexpected network destination');
    });
    const outcomes = Promise.allSettled([getPurchase(configuration(), 'first', true), getPurchase(configuration(), 'second', true)]);
    await entered.promise;
    await vi.waitFor(() => expect(oauthCalls).toBe(2));
    release.resolve(new Response(null, { status: 503 }));
    const failed = await outcomes;
    expect(failed.every(result => result.status === 'rejected' && result.reason.code === 'verification_unavailable')).toBe(true);
    expect(oauthCalls).toBe(2);
    await getPurchase(configuration(), 'retry', true);
    expect(oauthCalls).toBe(3);
  });

  it('a slower earlier exchange cannot replace a newer token with its older expiry', async () => {
    const { getPurchase } = await import('../src/google');
    const firstEntered = deferred<void>();
    const firstResponse = deferred<Response>();
    let oauthCalls = 0;
    const used: string[] = [];
    vi.spyOn(globalThis, 'fetch').mockImplementation(async (input, init) => {
      if (String(input) === oauthUrl) {
        oauthCalls++;
        if (oauthCalls === 1) { firstEntered.resolve(); return firstResponse.promise; }
        return Response.json({ access_token: 'newer-access', expires_in: 3600 });
      }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) {
        used.push(new Headers(init?.headers).get('Authorization')!);
        return Response.json({});
      }
      throw new Error('Unexpected network destination');
    });
    const first = getPurchase(configuration(), 'older-request', true);
    await firstEntered.promise;
    await getPurchase(configuration(), 'newer-request', true);
    firstResponse.resolve(Response.json({ access_token: 'older-access', expires_in: 1 }));
    await first;
    await getPurchase(configuration(), 'after-race', true);
    expect(oauthCalls).toBe(2);
    expect(used).toEqual(['Bearer newer-access', 'Bearer older-access', 'Bearer newer-access']);
  });

  it('a delayed 401 for an older token preserves a concurrently refreshed token', async () => {
    const { getPurchase } = await import('../src/google');
    const olderEntered = deferred<void>();
    const olderResponse = deferred<Response>();
    let oauthCalls = 0;
    const used: string[] = [];
    vi.spyOn(globalThis, 'fetch').mockImplementation(async (input, init) => {
      if (String(input) === oauthUrl) {
        oauthCalls++;
        return Response.json({ access_token: `access-${oauthCalls}`, expires_in: oauthCalls === 1 ? 1 : 3600 });
      }
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) {
        used.push(new Headers(init?.headers).get('Authorization')!);
        if (String(input).endsWith('/older')) { olderEntered.resolve(); return olderResponse.promise; }
        return Response.json({});
      }
      throw new Error('Unexpected network destination');
    });
    const older = getPurchase(configuration(), 'older', true);
    const rejected = expect(older).rejects.toMatchObject({ status: 503, code: 'verification_unavailable' });
    await olderEntered.promise;
    await getPurchase(configuration(), 'newer', true);
    olderResponse.resolve(new Response(null, { status: 401 }));
    await rejected;
    await getPurchase(configuration(), 'after-401', true);
    expect(oauthCalls).toBe(2);
    expect(used).toEqual(['Bearer access-1', 'Bearer access-2', 'Bearer access-2']);
  });

  it('a 401 for the current token still invalidates it without retrying or granting anything', async () => {
    const { getPurchase } = await import('../src/google');
    let oauthCalls = 0;
    let purchaseCalls = 0;
    vi.spyOn(globalThis, 'fetch').mockImplementation(async input => {
      if (String(input) === oauthUrl) return Response.json({ access_token: `access-${++oauthCalls}`, expires_in: 3600 });
      if (String(input).startsWith('https://androidpublisher.googleapis.com/')) {
        purchaseCalls++;
        return purchaseCalls === 1 ? new Response(null, { status: 401 }) : Response.json({});
      }
      throw new Error('Unexpected network destination');
    });
    await expect(getPurchase(configuration(), 'first', true)).rejects.toMatchObject({ status: 503, code: 'verification_unavailable' });
    expect(purchaseCalls).toBe(1);
    await getPurchase(configuration(), 'retry', true);
    expect(oauthCalls).toBe(2);
    expect(purchaseCalls).toBe(2);
  });
});
